  if (pathname === "/nucleus" || pathname.startsWith("/nucleus/")) {
    return `/nucleum${pathname.slice("/nucleus".length)}`;
  }
  if (pathname === "/static/nucleus" || pathname.startsWith("/static/nucleus/")) {
